mapper.select:
SELECT BID_CASE_ID
  FROM BID_CASES
 WHERE SOURCE_SLUG = #{sourceSlug}
   AND NOTICE_ID   = #{noticeId}

mapper.update:
UPDATE BID_CASES
   SET SOURCE_SLUG = #{sourceSlug,jdbcType=VARCHAR},
       NOTICE_ID   = #{noticeId,jdbcType=VARCHAR},
       TITLE       = #{title,jdbcType=VARCHAR},
       NOTICE_URL  = #{noticeUrl,jdbcType=VARCHAR}
 WHERE BID_CASE_ID = #{bidCaseId}

UPDATE BID_CASES
   SET FINALIZED_BY = #{finalizedBy,jdbcType=VARCHAR},
       FINALIZED_AT = #{finalizedAt,jdbcType=VARCHAR}
 WHERE BID_CASE_ID = #{bidCaseId}

UPDATE BID_CASES
   SET PARTICIPATION_DECISION = #{decision,jdbcType=CLOB,
         typeHandler=com.kbstar.kgi.ggreport.web.mapper.handler.ParticipationDecisionTypeHandler}


     , PARTICIPATION_STATUS = #{participationStatus}

 WHERE BID_CASE_ID = #{bidCaseId}

UPDATE BID_CASES
   SET PARTICIPATION_STATUS = #{participationStatus}
 WHERE BID_CASE_ID = #{bidCaseId}

mapper.select:
SELECT BID_CASE_ID FROM (
  SELECT BID_CASE_ID
    FROM BID_CASES
   WHERE INSTITUTION_ID = #{institutionId}
   ORDER BY SEQ_NO DESC
) WHERE ROWNUM = 1

mapper.update:
UPDATE BID_CASES
   SET RESEARCH_STATUS = #{researchStatus}
 WHERE BID_CASE_ID = #{bidCaseId}
